    size_t i;
    double p_mech = 0.0;
    double p_bus = 0.0;
    adcs_vec3_t tau = {0.0, 0.0, 0.0};
    adcs_vec3_t axis;
    double u, w, term;

    if ((wheels == NULL) || (wheel_torque == NULL) || (momentum == NULL) ||
        (body_torque == NULL) || (mechanical_power == NULL) || (bus_power == NULL))
        return ADCS_E_NULL;

    if ((count < 1U) || (count > 16U) || (!isfinite(efficiency)) ||
        (efficiency <= 0.0) || (efficiency > 1.0))
        return ADCS_E_RANGE;

    if (adcs_wheel_momentum(wheels, count, momentum) != ADCS_OK)
        return ADCS_E_RANGE;

    for (i = 0; i < count; i++) {
        if (!isfinite(wheel_torque[i]))
            return ADCS_E_RANGE;
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK)
            return ADCS_E_RANGE;
        u = wheel_torque[i];
        w = wheels[i].speed_rad_s;
        tau.x -= u * axis.x;
        tau.y -= u * axis.y;
        tau.z -= u * axis.z;
        term = u * w;
        p_mech += term;
        if (term > 0.0)
            p_bus += term / efficiency;
    }

    *body_torque = tau;
    *mechanical_power = p_mech;
    *bus_power = p_bus;

    return ADCS_OK;
}

