{
    size_t i;
    adcs_vec3_t axis;
    adcs_vec3_t scaled;
    double u_i, omega_i, p_i;
    adcs_status_t st;

    if ((wheels == NULL) || (wheel_torque == NULL) || (momentum == NULL) ||
        (body_torque == NULL) || (mechanical_power == NULL) || (bus_power == NULL)) {
        return ADCS_E_NULL;
    }

    if ((count < 1U) || (count > 16U) || (!isfinite(efficiency)) ||
        (efficiency <= 0.0) || (efficiency > 1.0)) {
        return ADCS_E_RANGE;
    }

    st = adcs_wheel_momentum(wheels, count, momentum);
    if (st != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    *body_torque = (adcs_vec3_t){0, 0, 0};
    *mechanical_power = 0.0;
    *bus_power = 0.0;

    for (i = 0; i < count; i++) {
        if (!isfinite(wheel_torque[i])) {
            return ADCS_E_RANGE;
        }
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK) {
            return ADCS_E_RANGE;
        }
        u_i = wheel_torque[i];
        omega_i = wheels[i].speed_rad_s;
        scaled = adcs_vec3_scale(&axis, -u_i);
        *body_torque = adcs_vec3_add(body_torque, &scaled);
        p_i = u_i * omega_i;
        *mechanical_power += p_i;
        if (p_i > 0.0) {
            *bus_power += p_i / efficiency;
        }
    }

    return ADCS_OK;
}
}

